/**
 * @file sensor_data.c
 * @brief Non-blocking sensor data cache used by LVGL pages.
 */

#include "sensor_data.h"

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

static pthread_mutex_t g_sensor_lock = PTHREAD_MUTEX_INITIALIZER;
static app_sensor_data_t g_sensor_data;
static uint32_t g_sensor_sequence;

static uint32_t sensor_now_ms(void)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }

    return (uint32_t)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

static void sensor_copy_status(char dest[APP_SENSOR_STATUS_MAX],
                               const char *status)
{
    const char *src = status ? status : "ok";

    snprintf(dest, APP_SENSOR_STATUS_MAX, "%s", src);
}

void app_sensor_data_init(void)
{
    pthread_mutex_lock(&g_sensor_lock);
    memset(&g_sensor_data, 0, sizeof(g_sensor_data));
    sensor_copy_status(g_sensor_data.status, "等待底层数据");
    g_sensor_sequence = 0;
    pthread_mutex_unlock(&g_sensor_lock);
}

void app_sensor_data_update(const app_sensor_data_t *data)
{
    app_sensor_data_t copy;
    const char *status;

    if (data == NULL) {
        return;
    }

    copy = *data;
    copy.valid = true;
    if (copy.timestamp_ms == 0) {
        copy.timestamp_ms = sensor_now_ms();
    }
    status = copy.status[0] != '\0' ? copy.status : "已接收";

    pthread_mutex_lock(&g_sensor_lock);
    copy.sequence = ++g_sensor_sequence;
    sensor_copy_status(copy.status, status);
    g_sensor_data = copy;
    pthread_mutex_unlock(&g_sensor_lock);
}

void app_sensor_data_update_value(int32_t value, const char *status)
{
    app_sensor_data_t data;

    memset(&data, 0, sizeof(data));
    data.primary_value = value;
    data.temperature_c = (float)value;
    sensor_copy_status(data.status, status);
    app_sensor_data_update(&data);
}

bool app_sensor_data_get(app_sensor_data_t *out)
{
    bool valid;

    if (out == NULL) {
        return false;
    }

    pthread_mutex_lock(&g_sensor_lock);
    *out = g_sensor_data;
    valid = g_sensor_data.valid;
    pthread_mutex_unlock(&g_sensor_lock);

    return valid;
}

uint32_t app_sensor_data_sequence(void)
{
    uint32_t sequence;

    pthread_mutex_lock(&g_sensor_lock);
    sequence = g_sensor_data.sequence;
    pthread_mutex_unlock(&g_sensor_lock);

    return sequence;
}

__attribute__((weak)) int app_sensor_fetch_latest(app_sensor_data_t *out)
{
    (void)out;
    return -ENODATA;
}

void app_sensor_poll_lower_layer(void)
{
    app_sensor_data_t data;

    memset(&data, 0, sizeof(data));
    if (app_sensor_fetch_latest(&data) == 0) {
        app_sensor_data_update(&data);
    }
}

