#include "state_manager.h"

/**********************
 *  GLOBAL FUNCTIONS
 **********************/

void state_manager_init(void)
{
    app_context_t *ctx = app_ctx_get();

    ctx->state.theme_variant = 0;               /* Light theme */
    ctx->state.chart_update_period_ms = 500;    /* 500ms */
    ctx->state.chart_value = 50;
    ctx->state.settings_changed = false;
}

uint32_t state_manager_toggle_theme(void)
{
    app_context_t *ctx = app_ctx_get();
    ctx->state.theme_variant = (ctx->state.theme_variant == 0) ? 1 : 0;
    ctx->state.settings_changed = true;
    return ctx->state.theme_variant;
}

void state_manager_set_chart_period(uint32_t period_ms)
{
    app_context_t *ctx = app_ctx_get();
    ctx->state.chart_update_period_ms = period_ms;
    ctx->state.settings_changed = true;
}

uint32_t state_manager_get_chart_period(void)
{
    return app_ctx_get()->state.chart_update_period_ms;
}

void state_manager_set_chart_value(int32_t value)
{
    app_context_t *ctx = app_ctx_get();
    ctx->state.chart_value = value;
}

int32_t state_manager_get_chart_value(void)
{
    return app_ctx_get()->state.chart_value;
}

bool state_manager_is_settings_dirty(void)
{
    return app_ctx_get()->state.settings_changed;
}

void state_manager_clear_dirty(void)
{
    app_ctx_get()->state.settings_changed = false;
}

