static void app_lvgldemo_fill_fb(uint8_t *fb, const struct fb_videoinfo_s *vinfo,
                                 const struct fb_planeinfo_s *pinfo, int frame)
{
  uint32_t x;
  uint32_t y;

  for (y = 0; y < vinfo->yres; y++)
    {
      uint8_t *line = fb + y * pinfo->stride;

      for (x = 0; x < vinfo->xres; x++)
        {
          uint8_t r = 0;
          uint8_t g = 0;
          uint8_t b = 0;

          switch (frame)
            {
              case 0:
                r = 255;
                break;

              case 1:
                g = 255;
                break;

              case 2:
                b = 255;
                break;

              case 3:
                r = 255;
                g = 255;
                b = 255;
                break;

              case 4:
                break;

              default:
                r = (uint8_t)((x * 255) / vinfo->xres);
                g = (uint8_t)((y * 255) / vinfo->yres);
                b = 96;
                break;
            }

          app_lvgldemo_put_pixel(line, x, vinfo->fmt, r, g, b);
        }
    }
}

static int app_lvgldemo_fbtest_once(const char *fb_path)
{
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  size_t map_len;
  uint8_t *fb;
  int fd;
  int frame;

  fd = open(fb_path, O_RDWR);
  if (fd < 0)
    {
      app_lvgldemo_log(LOG_ERR, "open %s failed: errno=%d", fb_path, errno);
      return -errno;
    }

  memset(&vinfo, 0, sizeof(vinfo));
  memset(&pinfo, 0, sizeof(pinfo));

  if (ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo) < 0)
    {
      app_lvgldemo_log(LOG_ERR, "FBIOGET_VIDEOINFO failed: errno=%d", errno);
      close(fd);
      return -errno;
    }

  if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo) < 0)
    {
      app_lvgldemo_log(LOG_ERR, "FBIOGET_PLANEINFO failed: errno=%d", errno);
      close(fd);
      return -errno;
    }

  app_lvgldemo_log(LOG_INFO,
                   "fbtest path=%s fmt=%u bpp=%u res=%ux%u stride=%u fblen=%zu",
                   fb_path, vinfo.fmt, pinfo.bpp, vinfo.xres, vinfo.yres,
                   pinfo.stride, pinfo.fblen);

  map_len = pinfo.fblen;
  if (map_len == 0)
    {
      map_len = (size_t)vinfo.yres * pinfo.stride;
    }

  fb = mmap(NULL, map_len, PROT_READ | PROT_WRITE,
            MAP_SHARED | MAP_FILE, fd, 0);
  if (fb == MAP_FAILED)
    {
      app_lvgldemo_log(LOG_ERR, "mmap %s failed: errno=%d", fb_path, errno);
      close(fd);
      return -errno;
    }

  for (frame = 0; frame < 6; frame++)
    {
#ifdef CONFIG_FB_UPDATE
      struct fb_area_s area;
#endif

      app_lvgldemo_log(LOG_INFO, "fbtest frame %d", frame);
      app_lvgldemo_fill_fb(fb, &vinfo, &pinfo, frame);
      msync(fb, map_len, MS_SYNC);

#ifdef CONFIG_FB_UPDATE
      area.x = 0;
      area.y = 0;
      area.w = vinfo.xres;
      area.h = vinfo.yres;
      ioctl(fd, FBIO_UPDATE, (unsigned long)&area);
#endif

      sleep(1);
    }

  munmap(fb, map_len);
  close(fd);
  app_lvgldemo_log(LOG_INFO, "fbtest done");
  return 0;
}

static int app_lvgldemo_fbtest(void)
{
  const char *fb_path = app_lvgldemo_primary_fb_path();
  const char *fallback;
  int ret;

  app_lvgldemo_wait_device(fb_path, CONFIG_APP_LOCAL_LVGLDEMO_DEVICE_WAIT_MS);
  ret = app_lvgldemo_fbtest_once(fb_path);
  if (ret == 0)
    {
      return 0;
    }

  fallback = app_lvgldemo_fallback_fb_path(fb_path);
  app_lvgldemo_log(LOG_WARNING, "primary fbtest failed, trying %s", fallback);
  app_lvgldemo_wait_device(fallback, CONFIG_APP_LOCAL_LVGLDEMO_DEVICE_WAIT_MS);
  return app_lvgldemo_fbtest_once(fallback);
}

static void app_lvgldemo_log_result(const char *fb_path,
                                    const lv_nuttx_result_t *result)
{
  lv_display_t *disp;
  int32_t hor_res;
  int32_t ver_res;
  lv_color_format_t color_format;

  if (result == NULL || result->disp == NULL)
    {
      app_lvgldemo_log(LOG_ERR, "lv_nuttx_init failed for %s: disp=NULL",
                       fb_path != NULL ? fb_path : "(null)");
      return;
    }

  disp = result->disp;
  hor_res = lv_display_get_horizontal_resolution(disp);
  ver_res = lv_display_get_vertical_resolution(disp);
  color_format = lv_display_get_color_format(disp);

  app_lvgldemo_log(LOG_INFO,
                   "LVGL display ready path=%s disp=%p indev=%p res=%ldx%ld "
                   "color_format=%d LV_COLOR_DEPTH=%d",
                   fb_path != NULL ? fb_path : "(null)",
                   disp, result->indev, (long)hor_res, (long)ver_res,
                   (int)color_format, LV_COLOR_DEPTH);
}

static int app_lvgldemo_nuttx_init(const char *fb_path,
                                   lv_nuttx_result_t *result)
{
  lv_nuttx_dsc_t info;

  memset(result, 0, sizeof(*result));
  lv_nuttx_dsc_init(&info);
  info.fb_path = fb_path;

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = CONFIG_APP_LOCAL_LVGLDEMO_INPUT_DEVPATH;
#endif

  app_lvgldemo_log(LOG_INFO, "lv_nuttx_init fb=%s input=%s",
                   info.fb_path != NULL ? info.fb_path : "(null)",
                   info.input_path != NULL ? info.input_path : "(null)");

  lv_nuttx_init(&info, result);
  app_lvgldemo_log_result(info.fb_path, result);

  return result->disp == NULL ? -ENODEV : 0;
}

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
static void lv_nuttx_uv_loop(uv_loop_t *loop, lv_nuttx_result_t *result)
{
  lv_nuttx_uv_t uv_info;
  void *data;

  uv_loop_init(loop);

  lv_memset(&uv_info, 0, sizeof(uv_info));
  uv_info.loop = loop;
  uv_info.disp = result->disp;
  uv_info.indev = result->indev;
