/****************************************************************************
 * Name: main or lv_demos_main
 *
 * Description:
 *
 * Input Parameters:
 *   Standard argc and argv
 *
 * Returned Value:
 *   Zero on success; a positive, non-zero value on failure.
 *
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_result_t result;
  const char *fb_path;
  int ret;

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  uv_loop_t ui_loop;
  lv_memzero(&ui_loop, sizeof(ui_loop));
#endif

  if (argc > 1 && strcmp(argv[1], "fbtest") == 0)
    {
      app_lvgldemo_log(LOG_INFO, "start fbtest");
      return app_lvgldemo_fbtest();
    }

  if (lv_is_initialized())
    {
      app_lvgldemo_log(LOG_ERR, "LVGL already initialized, aborting");
      LV_LOG_ERROR("LVGL already initialized! aborting.");
      return -1;
    }

  app_lvgldemo_log(LOG_INFO, "start argc=%d", argc);

#ifdef NEED_BOARDINIT
  /* Perform board-specific driver initialization */

  app_lvgldemo_log(LOG_INFO, "boardctl BOARDIOC_INIT");
  boardctl(BOARDIOC_INIT, 0);

#endif

  lv_init();
  app_lvgldemo_log(LOG_INFO, "lv_init done");

  fb_path = app_lvgldemo_primary_fb_path();
  app_lvgldemo_wait_device(fb_path, CONFIG_APP_LOCAL_LVGLDEMO_DEVICE_WAIT_MS);
  ret = app_lvgldemo_nuttx_init(fb_path, &result);

  if (ret < 0)
    {
      const char *fallback = app_lvgldemo_fallback_fb_path(fb_path);

      app_lvgldemo_log(LOG_WARNING,
                       "primary display init failed, trying fallback %s",
                       fallback);
      lv_nuttx_deinit(&result);

      app_lvgldemo_wait_device(fallback,
                               CONFIG_APP_LOCAL_LVGLDEMO_DEVICE_WAIT_MS);
      ret = app_lvgldemo_nuttx_init(fallback, &result);
    }

  if (ret < 0)
    {
      app_lvgldemo_log(LOG_ERR, "lv_demos initialization failure");
      LV_LOG_ERROR("lv_demos initialization failure!");
      lv_deinit();
      return 1;
    }

  bool autostart = argc > 1 &&
                   strcmp(argv[1], APP_LVGLDEMO_AUTOSTART_ARG) == 0;
  char **demo_argv = autostart ? &argv[2] : &argv[1];
  int demo_argc = autostart ? argc - 2 : argc - 1;

  app_lvgldemo_log(LOG_INFO, "creating LVGL demo page autostart=%d",
                   autostart ? 1 : 0);
  if (!lv_demos_create(demo_argv, demo_argc))
    {
      app_lvgldemo_log(LOG_ERR, "lv_demos_create failed");
      lv_demos_show_help();

      /* we can add custom demos here */

      goto demo_end;
    }

  lv_timer_handler();
  lv_refr_now(result.disp);
  app_lvgldemo_log(LOG_INFO, "first refresh requested");

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  lv_nuttx_uv_loop(&ui_loop, &result);
#else
  uint32_t loop_count = 0;
  while (1)
    {
      uint32_t idle;
      idle = lv_timer_handler();

      if (!autostart && (loop_count++ % 1000) == 0)
        {
          app_lvgldemo_log(LOG_INFO, "lv_timer_handler alive idle=%u ms",
                           (unsigned int)idle);
        }

      /* Minimum sleep of 1ms */

      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }
#endif

demo_end:
  lv_nuttx_deinit(&result);
  lv_deinit();

  return 0;
}

