/**
 * @file app_context.h
 * @brief Application context - centralized state and handle container.
 *
 * All global application state is collected into a single AppContext struct.
 * Modules receive a pointer to this struct rather than relying on scattered
 * extern variables. This improves testability and makes data flow explicit.
 */

#ifndef APP_CONTEXT_H
#define APP_CONTEXT_H

#ifdef __cplusplus
extern "C" {
#endif

/*********************
 *      INCLUDES
 *********************/
#include <lvgl/lvgl.h>
#include <stdint.h>
#include <stdbool.h>

/*********************
 *      DEFINES
 *********************/

/** Maximum number of pages that can be registered in the page manager. */
#define APP_MAX_PAGES       8

/** Invalid page ID sentinel. */
#define APP_PAGE_ID_INVALID 0xFF

/**********************
 *      TYPEDEFS
 **********************/

/**
 * Page IDs - each page in the application gets a unique ID.
 * Add new pages here and register them in page_manager.
 */
typedef enum {
    PAGE_HOME = 0,      /**< Home / launcher screen         */
    PAGE_LVGLDEMO,      /**< Integrated LVGL demo screen    */
    PAGE_CHART,         /**< Chart & widgets demo screen    */
    PAGE_SETTINGS,      /**< Settings / configuration       */
    PAGE_COUNT          /**< Total page count (keep last)   */
} app_page_id_t;

/**
 * Navigation actions requested by pages or logic layer.
 */
typedef enum {
    NAV_ACTION_NONE = 0,
    NAV_ACTION_PUSH,        /**< Push a new page onto the stack  */
    NAV_ACTION_POP,         /**< Pop back to previous page       */
    NAV_ACTION_REPLACE,     /**< Replace current page            */
    NAV_ACTION_HOME         /**< Go back to the root home page   */
} nav_action_t;

/**
 * Navigation request - queued by logic layer, consumed by page manager.
 */
typedef struct {
    nav_action_t action;
    app_page_id_t target_page;
} nav_request_t;

/**
 * Application-wide state managed by state_manager.
 */
typedef struct {
    uint32_t    theme_variant;      /**< 0 = light, 1 = dark           */
    uint32_t    chart_update_period_ms; /**< Chart refresh interval     */
    int32_t     chart_value;        /**< Current displayed chart value */
    bool        settings_changed;   /**< Dirty flag for settings       */
} app_state_t;

/**
 * Forward declaration for a page descriptor used by page_manager.
 */
typedef struct app_page_desc app_page_desc_t;

/**
 * Page lifecycle callbacks - each page implements these.
 */
typedef struct {
    /**
     * Create the page's UI. Returns the root lv_obj_t container.
     * The page manager will add it to a screen.
     */
    lv_obj_t * (*create)(lv_obj_t * parent);

    /**
     * Called when the page becomes visible. Optional (may be NULL).
     */
    void (*on_enter)(void);

    /**
     * Called when the page is about to become invisible. Optional.
     */
    void (*on_exit)(void);

    /**
     * Destroy the page and free resources. Called before page removal.
     */
    void (*destroy)(void);
} app_page_cbs_t;

/**
 * Page descriptor - one per registered page.
 */
struct app_page_desc {
    app_page_id_t   id;
    const char     *name;
    app_page_cbs_t  cbs;
    lv_obj_t       *root_obj;   /**< Root container, created by create() */
};

/**
 * Application context - the single source of truth.
 * Passed around as a pointer; no need for extern globals.
 */
typedef struct {
    /* Navigation */
    app_page_desc_t pages[APP_MAX_PAGES];
    uint32_t        page_count;
    int32_t         current_page_idx;  /**< Index into pages[] of active page */
    int32_t         page_stack[APP_MAX_PAGES]; /**< Simple page stack */
    int32_t         stack_top;         /**< Stack pointer (-1 = empty) */

    /* Pending navigation request */
    nav_request_t   pending_nav;
    bool            nav_requested;

    /* Application state */
    app_state_t     state;

    /* LVGL handles from NuttX init (display, input devices) */
    lv_display_t   *display;
    lv_indev_t     *indev;

    /* Main screen reference */
    lv_obj_t       *main_screen;
} app_context_t;

/**********************
 * GLOBAL PROTOTYPES
 **********************/

/**
 * Get the singleton application context.
 * First call allocates and zero-initializes it.
 */
app_context_t *app_ctx_get(void);

#ifdef __cplusplus
} /* extern "C" */
#endif

#endif /* APP_CONTEXT_H */

