static lv_obj_t *sensor_value_label;
static lv_obj_t *sensor_detail_label;
static lv_obj_t *demo_chart;
static lv_chart_series_t *demo_series;
static lv_timer_t *sensor_timer;
static uint32_t last_sensor_sequence;

static void sensor_timer_cb(lv_timer_t *timer);
static void delete_timer_cb(lv_event_t *e);
static void demo_button_cb(lv_event_t *e);

static lv_obj_t *create_demo_card(lv_obj_t *parent, const char *title)
{
    lv_obj_t *card = ui_comp_create_card(parent);

    lv_obj_t *label = lv_label_create(card);
    lv_label_set_text(label, title);
    ui_theme_apply_title_style(label);

    ui_comp_create_separator(card);
    return card;
}

static void demo_button_cb(lv_event_t *e)
{
    lv_obj_t *label = lv_event_get_user_data(e);

    if (label != NULL) {
        lv_label_set_text(label, "按钮已点击 / Button OK");
    }
}

static void update_sensor_widgets(const app_sensor_data_t *data)
{
    char detail[128];
    int32_t chart_value;

    if (data == NULL || !data->valid) {
        lv_label_set_text(sensor_status_label, "状态：等待底层数据传输");
        lv_label_set_text(sensor_value_label, "--");
        lv_label_set_text(sensor_detail_label,
                          "底层上传后页面将自动刷新，不阻塞渲染线程。");
        return;
    }

    chart_value = data->primary_value;
    if (chart_value < 0) {
        chart_value = 0;
    } else if (chart_value > 100) {
        chart_value = 100;
    }

    lv_label_set_text_fmt(sensor_status_label, "状态：%s  序号：%"LV_PRIu32,
                          data->status, data->sequence);
    lv_label_set_text_fmt(sensor_value_label, "%"LV_PRId32,
                          data->primary_value);
    snprintf(detail, sizeof(detail),
             "温度 %.1f C  湿度 %.1f %%  加速度 %.2f / %.2f / %.2f",
             (double)data->temperature_c, (double)data->humidity_pct,
             (double)data->accel_x, (double)data->accel_y,
             (double)data->accel_z);
    lv_label_set_text(sensor_detail_label, detail);

    if (demo_chart != NULL && demo_series != NULL) {
        lv_chart_set_next_value(demo_chart, demo_series,
                                (lv_coord_t)chart_value);
    }
}

static void sensor_timer_cb(lv_timer_t *timer)
{
    app_sensor_data_t data;

    LV_UNUSED(timer);

    app_sensor_poll_lower_layer();

    if (!app_sensor_data_get(&data)) {
        if (last_sensor_sequence != 0) {
            last_sensor_sequence = 0;
            update_sensor_widgets(NULL);
        }
        return;
    }

    if (data.sequence != last_sensor_sequence) {
        last_sensor_sequence = data.sequence;
        update_sensor_widgets(&data);
    }
}

static void delete_timer_cb(lv_event_t *e)
{
    lv_timer_t *timer = lv_event_get_user_data(e);

    if (lv_event_get_code(e) == LV_EVENT_DELETE && timer != NULL) {
        lv_timer_delete(timer);
    }
}

