+    printf("[%s] ", LVGLDEMO_PORT_TAG);
+
+    va_start(ap, fmt);
+    va_copy(syslog_ap, ap);
+    vprintf(fmt, ap);
+    printf("\n");
+    fflush(stdout);
+    va_end(ap);
+
+    vsyslog(priority, fmt, syslog_ap);
+    va_end(syslog_ap);
+}
+
+static const char *lvgldemo_port_primary_fb_path(void)
+{
+#ifdef CONFIG_LV_USE_NUTTX_LCD
+    return "/dev/lcd0";
+#else
+    return "/dev/fb0";
+#endif
+}
+
+static const char *lvgldemo_port_fallback_fb_path(const char *primary)
+{
+    if (primary != NULL && strcmp(primary, "/dev/fb0") == 0) {
+        return "/dev/lcd0";
+    }
+
+    return "/dev/fb0";
+}
+
+static bool lvgldemo_port_wait_device(const char *path, uint32_t timeout_ms)
+{
+    uint32_t waited_ms = 0;
+
+    if (path == NULL || path[0] == '\0') {
+        return false;
+    }
+
+    while (access(path, F_OK) < 0) {
+        if (waited_ms >= timeout_ms) {
+            lvgldemo_port_log(LOG_WARNING,
+                              "display device %s not found after %u ms: errno=%d",
+                              path, (unsigned int)waited_ms, errno);
+            return false;
+        }
+
+        usleep(50 * 1000);
+        waited_ms += 50;
+    }
+
+    lvgldemo_port_log(LOG_INFO, "display device ready: %s wait=%u ms",
+                      path, (unsigned int)waited_ms);
+    return true;
+}
+
+static void lvgldemo_port_put_pixel(uint8_t *line, uint32_t x, uint8_t fmt,
+                                    uint8_t r, uint8_t g, uint8_t b)
+{
+    switch (fmt) {
+    case FB_FMT_RGB16_565: {
+        uint16_t rgb565 = ((uint16_t)(r & 0xf8) << 8) |
+                          ((uint16_t)(g & 0xfc) << 3) |
+                          ((uint16_t)b >> 3);
+        ((uint16_t *)line)[x] = rgb565;
+        break;
+    }
+
+    case FB_FMT_RGB24:
+        line[x * 3 + 0] = r;
+        line[x * 3 + 1] = g;
+        line[x * 3 + 2] = b;
+        break;
+
+    case FB_FMT_RGB32:
+    case FB_FMT_RGBA32:
+        ((uint32_t *)line)[x] = 0xff000000u |
+                                ((uint32_t)r << 16) |
+                                ((uint32_t)g << 8) |
+                                b;
+        break;
+
+    default:
+        line[x] = (uint8_t)((r + g + b) / 3);
+        break;
+    }
+}
+
+static void lvgldemo_port_fill_fb(uint8_t *fb,
+                                  const struct fb_videoinfo_s *vinfo,
+                                  const struct fb_planeinfo_s *pinfo,
+                                  int frame)
+{
+    uint32_t x;
+    uint32_t y;
+
+    for (y = 0; y < vinfo->yres; y++) {
+        uint8_t *line = fb + y * pinfo->stride;
+
+        for (x = 0; x < vinfo->xres; x++) {
+            uint8_t r = 0;
+            uint8_t g = 0;
+            uint8_t b = 0;
+
+            switch (frame) {
+            case 0:
+                r = 255;
+                break;
+
+            case 1:
+                g = 255;
+                break;
+
+            case 2:
+                b = 255;
+                break;
+
+            case 3:
+                r = 255;
+                g = 255;
+                b = 255;
+                break;
+
+            case 4:
+                break;
+
+            default:
+                r = (uint8_t)((x * 255) / vinfo->xres);
+                g = (uint8_t)((y * 255) / vinfo->yres);
+                b = 96;
+                break;
+            }
+
+            lvgldemo_port_put_pixel(line, x, vinfo->fmt, r, g, b);
+        }
+    }
+}
+
+static int lvgldemo_port_fbtest_once(const char *fb_path)
+{
+    struct fb_videoinfo_s vinfo;
+    struct fb_planeinfo_s pinfo;
+    size_t map_len;
+    uint8_t *fb;
+    int fd;
+    int frame;
+
+    fd = open(fb_path, O_RDWR);
+    if (fd < 0) {
+        lvgldemo_port_log(LOG_ERR, "open %s failed: errno=%d",
+                          fb_path, errno);
+        return -errno;
+    }
+
+    memset(&vinfo, 0, sizeof(vinfo));
+    memset(&pinfo, 0, sizeof(pinfo));
+
+    if (ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo) < 0) {
+        lvgldemo_port_log(LOG_ERR, "FBIOGET_VIDEOINFO failed: errno=%d",
+                          errno);
+        close(fd);
+        return -errno;
+    }
+
+    if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo) < 0) {
+        lvgldemo_port_log(LOG_ERR, "FBIOGET_PLANEINFO failed: errno=%d",
+                          errno);
+        close(fd);
+        return -errno;
+    }
+
+    lvgldemo_port_log(LOG_INFO,
+                      "fbtest path=%s fmt=%u bpp=%u res=%ux%u stride=%u fblen=%zu",
+                      fb_path, vinfo.fmt, pinfo.bpp, vinfo.xres, vinfo.yres,
+                      pinfo.stride, pinfo.fblen);
+
+    map_len = pinfo.fblen;
+    if (map_len == 0) {
+        map_len = (size_t)vinfo.yres * pinfo.stride;
+    }
+
+    fb = mmap(NULL, map_len, PROT_READ | PROT_WRITE,
+              MAP_SHARED | MAP_FILE, fd, 0);
+    if (fb == MAP_FAILED) {
+        lvgldemo_port_log(LOG_ERR, "mmap %s failed: errno=%d",
+                          fb_path, errno);
+        close(fd);
+        return -errno;
+    }
+
+    for (frame = 0; frame < 6; frame++) {
+#ifdef CONFIG_FB_UPDATE
+        struct fb_area_s area;
+#endif
+
+        lvgldemo_port_log(LOG_INFO, "fbtest frame %d", frame);
+        lvgldemo_port_fill_fb(fb, &vinfo, &pinfo, frame);
+        msync(fb, map_len, MS_SYNC);
+
+#ifdef CONFIG_FB_UPDATE
+        area.x = 0;
+        area.y = 0;
+        area.w = vinfo.xres;
+        area.h = vinfo.yres;
+        ioctl(fd, FBIO_UPDATE, (unsigned long)&area);
+#endif
+
+        sleep(1);
+    }
+
+    munmap(fb, map_len);
+    close(fd);
+    lvgldemo_port_log(LOG_INFO, "fbtest done");
+    return 0;
+}
+
+void lvgldemo_port_set_args(int argc, char *argv[])
+{
+    g_demo_argc = argc;
+    g_demo_argv = argv;
+    g_demo_created = false;
+}
+
+bool lvgldemo_port_create(void)
+{
+    if (g_demo_created) {
+        return true;
+    }
+
+    lvgldemo_port_log(LOG_INFO, "creating LVGL demo argc=%d", g_demo_argc);
+    if (!lv_demos_create(g_demo_argv, g_demo_argc)) {
+        lvgldemo_port_log(LOG_ERR, "lv_demos_create failed");
+        lv_demos_show_help();
+        return false;
+    }
+
+    lv_timer_handler();
+    lv_refr_now(NULL);
+    g_demo_created = true;
+    lvgldemo_port_log(LOG_INFO, "first refresh requested");
+    return true;
+}
+
+int lvgldemo_port_fbtest(void)
+{
+    const char *fb_path = lvgldemo_port_primary_fb_path();
+    const char *fallback;
+    int ret;
+
+    lvgldemo_port_wait_device(fb_path, CONFIG_APP_LVGL_APP_DEVICE_WAIT_MS);
+    ret = lvgldemo_port_fbtest_once(fb_path);
+    if (ret == 0) {
+        return 0;
+    }
+
+    fallback = lvgldemo_port_fallback_fb_path(fb_path);
+    lvgldemo_port_log(LOG_WARNING, "primary fbtest failed, trying %s",
+                      fallback);
+    lvgldemo_port_wait_device(fallback, CONFIG_APP_LVGL_APP_DEVICE_WAIT_MS);
+    return lvgldemo_port_fbtest_once(fallback);
+}
