+static void clean_screen_except_anchor(lv_obj_t *screen)
+{
+    uint32_t child_count;
+    uint32_t idx = 0;
+
+    if (screen == NULL) {
+        return;
+    }
+
+    child_count = lv_obj_get_child_count(screen);
+    while (idx < child_count) {
+        lv_obj_t *child = lv_obj_get_child(screen, (int32_t)idx);
+
+        if (child == s_page_anchor) {
+            idx++;
+            continue;
+        }
+
+        lv_obj_delete(child);
+        child_count--;
+    }
+}
+
+static lv_obj_t *create_error_page(lv_obj_t *parent)
