+    lv_obj_set_style_border_width(s_page_anchor, 0, 0);
+    lv_obj_set_style_pad_all(s_page_anchor, 16, 0);
+    lv_obj_set_flex_flow(s_page_anchor, LV_FLEX_FLOW_COLUMN);
+    lv_obj_set_flex_align(s_page_anchor, LV_FLEX_ALIGN_CENTER,
+                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
+
+    label = lv_label_create(s_page_anchor);
+    lv_label_set_text(label, "LVGL demo 创建失败，请检查 CONFIG_LV_USE_DEMO_*");
+    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
+    lv_obj_set_width(label, LV_PCT(100));
+    lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, 0);
+    ui_theme_apply_text_style(label);
+
+    LV_UNUSED(parent);
+    return s_page_anchor;
+}
+
+static lv_obj_t *lvgldemo_create(lv_obj_t *parent)
+{
+    if (parent == NULL) {
+        syslog(LOG_ERR, "[%s] parent screen is NULL\n", LOG_TAG);
+        return NULL;
+    }
+
+    lv_obj_clean(parent);
+
+    s_page_anchor = lv_obj_create(parent);
+    lv_obj_add_flag(s_page_anchor, LV_OBJ_FLAG_HIDDEN);
+    lv_obj_set_size(s_page_anchor, 1, 1);
+    lv_obj_set_style_bg_opa(s_page_anchor, LV_OPA_TRANSP, 0);
