    35	static int button_test_poll(void) {
    36	  struct pollfd fds;
    37	  int fd;
    38	  int ret;
    39	  uint8_t buffer[16];
    40	
    41	  /* 打开按钮设备 */
    42	  fd = open(BUTTON_DEVICE, O_RDONLY);
    43	  if (fd < 0) {
