    47	
    48	  syslog(LOG_INFO, "Button test started. Press and release the button...\n");
    49	  syslog(LOG_INFO, "Press Ctrl+C to exit.\n");
    50	
    51	  /* 配置poll */
    52	  fds.fd = fd;
    53	  fds.events = POLLIN;
    54	  fds.revents = 0;
    55	
    56	  while (1) {
    57	    /* 等待按钮事件 */
    58	    ret = poll(&fds, 1, -1);
    59	    if (ret < 0) {
    60	      if (errno == EINTR) {
    61	        syslog(LOG_INFO, "Test interrupted by user.\n");
    62	        break;
    63	      }
    64	      syslog(LOG_INFO, "ERROR: poll failed: %d\n", errno);
    65	      break;
    66	    }
    67	
    68	    if (fds.revents & POLLIN) {
    69	      /* 读取按钮状态 */
    70	      ret = read(fd, buffer, sizeof(buffer));
    71	      if (ret > 0) {
    72	        /* 按钮状态在buffer中，格式为按钮ID和状态 */
    73	        if (ret >= 2) {
    74	          uint8_t state = (buffer[0] >> BUTTON_ID1) & 0x01;
    75	
