    77	        } else {
    78	          syslog(LOG_INFO, "Received button event with %d bytes\n", ret);
    79	        }
    80	      } else if (ret < 0) {
    81	        syslog(LOG_INFO, "ERROR: read failed: %d\n", errno);
    82	        break;
    83	      }
    84	    }
    85	  }
    86	
    87	  close(fd);
    88	  return 0;
    89	}
